export const getContrastRevision = (topicId, index) => CONTRAST_REVISIONS[`${topicId}:${index}`]
export const contrastRevisionForSeed = (seed, seeds) => {
 for (const [topicId, rows] of Object.entries(seeds)) { const index = rows.indexOf(seed); if (index >= 0) return getContrastRevision(topicId, index) }
 return undefined
}
